	            if (token.Type == VARIABLE_NAME && IsFunctionVariableReferenceAt(index))
	                return true;

	            if (FunctionExpressionStarters.Contains(text))
	                return true;

	            if (text == "(")
	                depth++;
	            else if (text == ")")
	            {
	                if (depth == 0)
	                    return false;

	                depth--;
	            }
	        }
	    }

